package main

import (
	"context"
	"errors"
	"fmt"
	"time"
)

// slowOp simulates work that respects cancellation.
func slowOp(ctx context.Context) (string, error) {
	select {
	case <-time.After(300 * time.Millisecond): // pretend the work takes 300ms
		return "done", nil
	case <-ctx.Done(): // cancelled or timed out
		return "", ctx.Err()
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel() // ALWAYS call cancel to release the timer

	res, err := slowOp(ctx)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			fmt.Println("operation timed out")
		} else {
			fmt.Println("operation cancelled:", err)
		}
		return
	}
	fmt.Println("result:", res)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type ctxKey string // unexported key type avoids collisions

const reqIDKey ctxKey = "reqID"

func worker(ctx context.Context, id int, wg *sync.WaitGroup) {
	defer wg.Done()
	reqID, _ := ctx.Value(reqIDKey).(string) // request-scoped value
	for {
		select {
		case <-ctx.Done(): // parent cancelled -> all workers stop
			fmt.Printf("worker %d (%s) stopping: %v\n", id, reqID, ctx.Err())
			return
		case <-time.After(20 * time.Millisecond):
			// simulate a unit of cancellable work
		}
	}
}

func main() {
	ctx := context.WithValue(context.Background(), reqIDKey, "req-123")
	ctx, cancel := context.WithCancel(ctx)

	var wg sync.WaitGroup
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go worker(ctx, i, &wg)
	}

	time.Sleep(50 * time.Millisecond)
	cancel()  // signal all workers to stop
	wg.Wait() // wait for clean shutdown
	fmt.Println("all workers stopped")
}
